package vn.edu.eaut.lab9.service;import jakarta.persistence.*;import vn.edu.eaut.lab9.config.JPAUtil;import vn.edu.eaut.lab9.model.*;import java.time.*;
public class SeedData{public static void init(){EntityManager e=JPAUtil.getEntityManagerFactory().createEntityManager();try{Long n=e.createQuery("select count(l) from LopHoc l",Long.class).getSingleResult();if(n>0)return;e.getTransaction().begin();LopHoc a=new LopHoc("CNTT K20A");LopHoc b=new LopHoc("CNTT K20B");e.persist(a);e.persist(b);MonHoc j=new MonHoc("IT3242","Công nghệ Java",3),db=new MonHoc("IT3010","Cơ sở dữ liệu",3);e.persist(j);e.persist(db);SinhVien s1=new SinhVien("SV001","Nguyễn Văn An","an@example.com",a,LocalDate.of(2005,1,10));SinhVien s2=new SinhVien("SV002","Trần Thị Bình","binh@example.com",a,LocalDate.of(2005,5,20));SinhVien s3=new SinhVien("SV003","Lê Minh Cường","cuong@example.com",b,LocalDate.of(2004,9,15));e.persist(s1);e.persist(s2);e.persist(s3);e.persist(new Diem(s1,j,9,8,9));e.persist(new Diem(s2,j,8,7,8));e.persist(new Diem(s3,db,7,8,7));e.getTransaction().commit();}catch(RuntimeException x){if(e.getTransaction().isActive())e.getTransaction().rollback();throw x;}finally{e.close();}}}
